// El mensaje generado por Ollama viene aquí
const aiMessage = $input.item.json.text;

// Los datos originales del Webhook
const userName  = $('Webhook').item.json.body.name;
const userEmail = $('Webhook').item.json.body.email;

// Limpiamos etiquetas <think> que a veces genera el modelo
const cleanMessage = aiMessage.replace(/<think>[\s\S]*?<\/think>/g, '').trim();

// Construimos el HTML del email
const htmlBody = `
<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;padding:20px;">
  <div style="background:#4f46e5;padding:24px;border-radius:12px 12px 0 0;">
    <h1 style="color:white;margin:0;font-size:22px;">¡Bienvenido ${userName}! 🎉</h1>
  </div>
  <div style="background:#f9fafb;padding:24px;border-radius:0 0 12px 12px;border:1px solid #e5e7eb;">
    <p style="color:#374151;font-size:16px;line-height:1.7;white-space:pre-line;">${cleanMessage}</p>
    <hr style="border:none;border-top:1px solid #e5e7eb;margin:20px 0;">
    <p style="color:#9ca3af;font-size:12px;">Mensaje generado por Mi IA local 🤖</p>
  </div>
</div>`;

return [{
  json: {
    to:      userEmail,
    subject: `¡Bienvenido ${userName}! Mi IA tiene un mensaje para ti 🤖`,
    html:    htmlBody,
    text:    cleanMessage
  }
}];
